window.docContents[165].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Additional-Exercises--Exercise___-STLC-with-Arithmetic--Preservation":{"contents":"\n\nHint: you will need to define and prove the same helper lemmas we used\nbefore.theorem preservation (t t' : Tm) (τ : Ty)\n    (hτ : <{ ∅ ⊢ ~t ⦂ ~τ }>) (hs : t ⟶ t') : <{ ∅ ⊢ ~t' ⦂ ~τ }> := by\n  solution!\n    generalize hΓ : (∅ : Context) = Γ at hτ\n    induction hτ generalizing t' with\n    | var => cases hs\n    | abs => cases hs\n    | const => cases hs\n    | app Γ τ₁ τ₂ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n      subst hΓ\n      cases hs with\n      | appAbs _ _ _ _ _ =>\n        -- The one interesting case: the desired result is the substitution lemma.\n        cases h₁ with\n        | abs _ _ _ _ _ hb =>\n          apply substitution_preserves_typing\n          · exact hb\n          · exact h₂\n      | app1 _ t₁' _ h =>\n        constructor\n        · apply ih₁\n          · exact h\n          · rfl\n        · exact h₂\n      | app2 _ _ t₂' _ h =>\n        constructor\n        · exact h₁\n        · apply ih₂\n          · exact h\n          · rfl\n    | succ Γ t₁ h ih =>\n      subst hΓ\n      cases hs with\n      | succ _ t₁' hst =>\n        constructor\n        apply ih\n        · exact hst\n        · rfl\n      | succConst n => constructor\n    | pred Γ t₁ h ih =>\n      subst hΓ\n      cases hs with\n      | pred _ t₁' hst =>\n        constructor\n        apply ih\n        · exact hst\n        · rfl\n      | predConst n => constructor\n    | mult Γ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n      subst hΓ\n      cases hs with\n      | multConst _ _ => constructor\n      | mult1 _ t₁' _ hst =>\n        constructor\n        · apply ih₁\n          · exact hst\n          · rfl\n        · exact h₂\n      | mult2 _ _ t₂' _ hst =>\n        constructor\n        · exact h₁\n        · apply ih₂\n          · exact hst\n          · rfl\n    | ite0 Γ t₁ t₂ t₃ τ₀ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n      subst hΓ\n      cases hs with\n      | if0Step _ t₁' _ _ hst =>\n        constructor\n        · apply ih₁\n          · exact hst\n          · rfl\n        · exact h₂\n        · exact h₃\n      | if0Zero => exact h₂\n      | if0Nonzero => exact h₃\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC\u0009Additional Exercises\u0009Exercise: STLC with Arithmetic","header":"6.7.1.2. Preservation","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Additional-Exercises--Exercise___-STLC-with-Arithmetic--Preservation"}});